pat=re.compile(r'^test result: (\w+)\. (\d+) passed; (\d+) failed; (\d+) ignored; (\d+) measured; (\d+) filtered out; finished in ([^\n]+)$',re.M)
def parse(where,name,retain=True):
 s=(where/(name+'.stdout')).read_text();e=(where/(name+'.stderr')).read_text();ss=list(pat.finditer(s));hh=list(re.finditer(r'^running (\d+) tests?$',s,re.M));targets=[]
 for ln,line in enumerate(e.splitlines(),1):
  z=re.match(r'^\s+Running (.+) \((.+)\)$',line)
  if z:targets.append({'kind':'test_binary','cargo_target':z.group(1),'executable':z.group(2),'stderr_line':ln,'binary_name':re.sub(r'-[0-9a-f]{16}$','',pathlib.Path(z.group(2)).name)})
  z=re.match(r'^\s+Doc-tests (.+)$',line)
  if z:targets.append({'kind':'doctest','crate':z.group(1),'stderr_line':ln})
 assert len(ss)==len(hh)==len(targets)
 groups=[];ignored=[];passedkeys=[]
 for idx,(sm,header,target) in enumerate(zip(ss,hh,targets)):
  block=s[header.end():sm.start()];passed=re.findall(r'^test (.+) \.\.\. ok$',block,re.M);ig=re.findall(r'^test (.+) \.\.\. ignored(?:, (.*))?$',block,re.M)
  counts={k:int(sm.group(i)) for k,i in [('passed',2),('failed',3),('ignored',4),('measured',5),('filtered_out',6)]}
  assert sm.group(1)=='ok' and len(passed)==counts['passed'] and len(ig)==counts['ignored'] and counts['failed']==0
  assert int(header.group(1))==counts['passed']+counts['ignored']+counts['failed']+counts['measured']
  group={'sequence':idx+1,'target':target,'running_count':int(header.group(1)),'summary_stdout_line':s[:sm.start()].count('\n')+1,'counts':counts,'duration':sm.group(7)}
  if target['kind']=='doctest' or target.get('cargo_target') in ['tests/p8_scale.rs','tests/snapshot_leaf_batching.rs'] or name.startswith('04'):group['actual_passed_test_names']=passed
  groups.append(group);ignored.extend({'target':target,'test_name':n,'reason':reason} for n,reason in ig)
  passedkeys.extend((target['kind'],target.get('crate',target.get('binary_name')),n) for n in passed)
 totals={k:sum(g['counts'][k] for g in groups) for k in ['passed','failed','ignored','measured','filtered_out']}
 assert len(set(passedkeys))==totals['passed']
 return {'raw_stdout':ident(where/(name+'.stdout')),'raw_stderr':ident(where/(name+'.stderr')),'harness_groups':groups,'totals':totals,'individual_ok_lines':len(passedkeys),'individual_ignored_lines':len(ignored),'ignored_tests':ignored,'zero_case_groups':sum(g['running_count']==0 for g in groups),'group_count':len(groups)},set(passedkeys)
